REVOKE EXECUTE ON FUNCTION public.complete_registration(jsonb) FROM anon; REVOKE EXECUTE ON FUNCTION public.reserve_ticket(text) FROM anon; REVOKE EXECUTE ON FUNCTION public.check_in_ticket(uuid) FROM anon; REVOKE EXECUTE ON FUNCTION public.create_profile() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.create_profile() TO service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;